--region handler
---详情按钮点击回调
function CommonRoleUpNodeCell:BtnDetailsOnClickHandler()
    local hasCard = cardComponent:IsHasCard(self.data.refId)
    if hasCard then
        local id = cardComponent:GetIdByCardId(self.data.refId)
        CardProgressionUtils.OpenDialog(Constants.UITypeIds.CultivateMain, {playerCardId = id}, UICommonUtils.GetShowDialogArguments())
    else
        local gachaponUtils = import('Game.Gachapon.GachaponUtils')
        gachaponUtils.OpenDetail(self.data.refId, self.excludeDialogs, {showJumpBtn = true})
    end
    if self.callBack then
        self.callBack()
    end
end
--endregion handler

--region public
---刷新节点
function CommonRoleUpNodeCell:RefreshCellShow(data,callBack,excludeDialogs)
    self.data = data
    self.callBack = callBack
    self.excludeDialogs = excludeDialogs
    ---@type CardHeadNode
    local scr = CfUtils.GetLuaScr(self.CommonSmallHeadNode, "Game.Behaviours.CardHeadNode")
    if isNull(scr) then return end

    if checkInt(data.type) ~= Constants.UpRoleBuffType.CardId then return end
    
    local hasCard = cardComponent:IsHasCard(data.refId)
    if hasCard then
        local cardDojo = cardComponent:GetCardByConfId(data.refId)
        scr:FreshNode(cardDojo, false, 1)
    else
        scr:FreshNodeByCardVo(data.refId, 1, false)
    end
    CfUtils.SetUISwitchText(self.TxtDesc, hasCard and 1 or 2)
    CfUtils.SetActive(self.ImgMask, hasCard == false)

    local vo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(data.commonAddId)
    if vo then
        CfUtils.FillText(self.TxtDesc, vo.desc)
    end
end
--endregion public

--region private
--endregion private

return CommonRoleUpNodeCell